macro_rules! deps {
    () => {
        Limb!();
    };
}

macro_rules! small {
    () => {
        deps!();
        mod small { use super :: * ; # [doc = " Implied AddAssign implementation for adding a small integer to bigint."] # [doc = ""] # [doc = " Allows us to choose a start-index in x to store, to allow incrementing"] # [doc = " from a non-zero start."] # [inline] pub fn iadd_impl (x : & mut Vec < Limb > , y : Limb , xstart : usize) { if x . len () <= xstart { x . push (y) ; } else { let mut carry = scalar :: iadd (& mut x [xstart] , y) ; let mut size = xstart + 1 ; while carry && size < x . len () { carry = scalar :: iadd (& mut x [size] , 1) ; size += 1 ; } if carry { x . push (1) ; } } } # [doc = " AddAssign small integer to bigint."] # [inline] pub fn iadd (x : & mut Vec < Limb > , y : Limb) { iadd_impl (x , y , 0) ; } # [doc = " SubAssign small integer to bigint."] # [doc = " Does not do overflowing subtraction."] # [inline] pub fn isub_impl (x : & mut Vec < Limb > , y : Limb , xstart : usize) { debug_assert ! (x . len () > xstart && (x [xstart] >= y || x . len () > xstart + 1)) ; let mut carry = scalar :: isub (& mut x [xstart] , y) ; let mut size = xstart + 1 ; while carry && size < x . len () { carry = scalar :: isub (& mut x [size] , 1) ; size += 1 ; } normalize (x) ; } # [doc = " MulAssign small integer to bigint."] # [inline] pub fn imul (x : & mut Vec < Limb > , y : Limb) { let mut carry : Limb = 0 ; for xi in & mut * x { carry = scalar :: imul (xi , y , carry) ; } if carry != 0 { x . push (carry) ; } } # [doc = " Mul small integer to bigint."] # [inline] pub fn mul (x : & [Limb] , y : Limb) -> Vec < Limb > { let mut z = Vec :: < Limb > :: default () ; z . extend_from_slice (x) ; imul (& mut z , y) ; z } # [doc = " MulAssign by a power."] # [doc = ""] # [doc = " Theoretically..."] # [doc = ""] # [doc = " Use an exponentiation by squaring method, since it reduces the time"] # [doc = " complexity of the multiplication to ~`O(log(n))` for the squaring,"] # [doc = " and `O(n*m)` for the result. Since `m` is typically a lower-order"] # [doc = " factor, this significantly reduces the number of multiplications"] # [doc = " we need to do. Iteratively multiplying by small powers follows"] # [doc = " the nth triangular number series, which scales as `O(p^2)`, but"] # [doc = " where `p` is `n+m`. In short, it scales very poorly."] # [doc = ""] # [doc = " Practically...."] # [doc = ""] # [doc = " Exponentiation by Squaring:"] # [doc = "     running 2 tests"] # [doc = "     test bigcomp_f32_lexical ... bench:       1,018 ns/iter (+/- 78)"] # [doc = "     test bigcomp_f64_lexical ... bench:       3,639 ns/iter (+/- 1,007)"] # [doc = ""] # [doc = " Exponentiation by Iterative Small Powers:"] # [doc = "     running 2 tests"] # [doc = "     test bigcomp_f32_lexical ... bench:         518 ns/iter (+/- 31)"] # [doc = "     test bigcomp_f64_lexical ... bench:         583 ns/iter (+/- 47)"] # [doc = ""] # [doc = " Exponentiation by Iterative Large Powers (of 2):"] # [doc = "     running 2 tests"] # [doc = "     test bigcomp_f32_lexical ... bench:         671 ns/iter (+/- 31)"] # [doc = "     test bigcomp_f64_lexical ... bench:       1,394 ns/iter (+/- 47)"] # [doc = ""] # [doc = " Even using worst-case scenarios, exponentiation by squaring is"] # [doc = " significantly slower for our workloads. Just multiply by small powers,"] # [doc = " in simple cases, and use precalculated large powers in other cases."] pub fn imul_pow5 (x : & mut Vec < Limb > , n : u32) { use super :: large :: KARATSUBA_CUTOFF ; let small_powers = POW5_LIMB ; let large_powers = large_powers :: POW5 ; if n == 0 { return ; } let bit_length = 32 - n . leading_zeros () as usize ; debug_assert ! (bit_length != 0 && bit_length <= large_powers . len ()) ; if x . len () + large_powers [bit_length - 1] . len () < 2 * KARATSUBA_CUTOFF { let step = small_powers . len () - 1 ; let power = small_powers [step] ; let mut n = n as usize ; while n >= step { imul (x , power) ; n -= step ; } imul (x , small_powers [n]) ; } else { let mut idx : usize = 0 ; let mut bit : usize = 1 ; let mut n = n as usize ; while n != 0 { if n & bit != 0 { debug_assert ! (idx < large_powers . len ()) ; large :: imul (x , large_powers [idx]) ; n ^= bit ; } idx += 1 ; bit <<= 1 ; } } } # [doc = " Get number of leading zero bits in the storage."] # [inline] pub fn leading_zeros (x : & [Limb]) -> usize { x . last () . map_or (0 , | x | x . leading_zeros () as usize) } # [doc = " Calculate the bit-length of the big-integer."] # [inline] pub fn bit_length (x : & [Limb]) -> usize { let bits = mem :: size_of :: < Limb > () * 8 ; let nlz = leading_zeros (x) ; bits . checked_mul (x . len ()) . map_or_else (usize :: max_value , | v | v - nlz) } # [doc = " Shift-left bits inside a buffer."] # [doc = ""] # [doc = " Assumes `n < Limb::BITS`, IE, internally shifting bits."] # [inline] pub fn ishl_bits (x : & mut Vec < Limb > , n : usize) { let bits = mem :: size_of :: < Limb > () * 8 ; debug_assert ! (n < bits) ; if n == 0 { return ; } let rshift = bits - n ; let lshift = n ; let mut prev : Limb = 0 ; for xi in & mut * x { let tmp = * xi ; * xi <<= lshift ; * xi |= prev >> rshift ; prev = tmp ; } let carry = prev >> rshift ; if carry != 0 { x . push (carry) ; } } # [doc = " Shift-left `n` digits inside a buffer."] # [doc = ""] # [doc = " Assumes `n` is not 0."] # [inline] pub fn ishl_limbs (x : & mut Vec < Limb > , n : usize) { debug_assert ! (n != 0) ; if ! x . is_empty () { x . reserve (n) ; x . splice (.. 0 , iter :: repeat (0) . take (n)) ; } } # [doc = " Shift-left buffer by n bits."] # [inline] pub fn ishl (x : & mut Vec < Limb > , n : usize) { let bits = mem :: size_of :: < Limb > () * 8 ; let rem = n % bits ; let div = n / bits ; ishl_bits (x , rem) ; if div != 0 { ishl_limbs (x , div) ; } } # [doc = " Normalize the container by popping any leading zeros."] # [inline] pub fn normalize (x : & mut Vec < Limb >) { while x . last () == Some (& 0) { x . pop () ; } } }
    };
}

small!();